<script lang="ts">
 import {onMount} from 'svelte';import {accountRequest,applyTheme,type Account,type Grant} from './accounts';import type {Kind} from './types';
 export let user:Account;export let token:string;export let libraries:{id:string;name:string;kind:string}[]=[];export let admin=false;export let changed:(a:Account)=>void;export let logout:()=>void;
 let users:Account[]=[];let selected:Account|null=null;let password='';let current='';let repeat='';let busy=false;let error='';let notice='';let invitation='';let theme=user.theme;
 const names:Record<Kind,string>={films:'Films',series:'Séries',music:'Musique'};const actions:{id:keyof Grant;label:string}[]=[{id:'view',label:'Voir'},{id:'play',label:'Lire'},{id:'edit',label:'Modifier les fiches et affiches'},{id:'request',label:'Demander des téléchargements'}];
 async function load(){try{users=await accountRequest(token,'accounts')}catch(e){error=String(e)}}
 function edit(a?:Account){selected=a?structuredClone(a):{id:'',name:'',admin:false,disabled:false,pending:true,kinds:['films','series','music'],libraries:{},theme:'light'};password='';invitation='';error='';notice='';}
 function grant(id:string,action:keyof Grant,value:boolean){if(!selected)return;const g={...(selected.libraries[id]??{view:false,play:false,edit:false,request:false}),[action]:value};if(action!=='view'&&value)g.view=true;if(action==='view'&&!value){g.play=false;g.edit=false;g.request=false}selected={...selected,libraries:{...selected.libraries,[id]:g}};}
 function kind(k:Kind,value:boolean){if(selected)selected={...selected,kinds:value?[...selected.kinds,k]:selected.kinds.filter(v=>v!==k)}}
 function showInvite(code:string){invitation=location.origin+location.pathname+'#invitation='+encodeURIComponent(code)}
 async function save(event:SubmitEvent){event.preventDefault();if(!selected)return;busy=true;error='';notice='';invitation='';try{const own=selected.id===user.id;const result=await accountRequest(token,'accounts'+(selected.id?'/'+selected.id:''),selected.id?'PUT':'POST',{account:selected,password});password='';selected=result.user;if(result.invitation)showInvite(result.invitation);notice=result.invitation?'Compte créé. Transmettez ce lien à son destinataire.':'Compte enregistré. Les anciennes sessions ont été révoquées.';if(own){logout();return}await load();}catch(e){error=e instanceof Error?e.message:'Compte non enregistré.'}finally{busy=false}}
 async function renew(){if(!selected)return;busy=true;error='';try{const data=await accountRequest(token,'accounts/'+selected.id+'/invitation','POST');showInvite(data.invitation);notice='Nouveau lien créé : le précédent ne fonctionne plus.';}catch(e){error=String(e)}finally{busy=false}}
 async function changePassword(event:SubmitEvent){event.preventDefault();if(password!==repeat){error='Les mots de passe sont différents.';return}busy=true;error='';try{await accountRequest(token,'account/password','PUT',{current,password});current='';password='';repeat='';logout()}catch(e){error=e instanceof Error?e.message:'Mot de passe non modifié.'}finally{busy=false}}
 async function saveTheme(){try{const a=await accountRequest(token,'account/preferences','PUT',{theme});applyTheme(a.theme);changed(a);notice='Apparence enregistrée pour votre compte.'}catch(e){error=String(e)}}
 async function copy(){try{await navigator.clipboard.writeText(invitation);notice='Lien copié.'}catch{notice='Sélectionnez le lien ci-dessous pour le copier.'}}
 onMount(()=>{if(admin)void load()});
</script>
<section class="account-settings">
{#if admin}<div class="account-heading"><div><span class="eyebrow">CHACUN SON ESPACE</span><h2>Utilisateurs</h2><p>Choisissez qui peut accéder à votre collection et ce que chacun peut y faire.</p></div><button class="secondary" onclick={()=>edit()}>Créer un compte</button></div>
<div class="account-list">{#each users as a}<button class:selected={selected?.id===a.id} onclick={()=>edit(a)}><strong>{a.name}</strong><span>{a.disabled?'Désactivé':a.pending?'Invitation en attente':a.admin?'Administrateur':'Utilisateur'}</span></button>{/each}</div>
{#if selected}<form class="account-editor" onsubmit={save}><h3>{selected.id?'Modifier le compte':'Nouveau compte'}</h3><label>Nom d’utilisateur<input required maxlength="48" pattern="[a-zA-Z0-9_.-]+" autocomplete="off" bind:value={selected.name}/></label>
<label>{selected.id?'Nouveau mot de passe (facultatif)':'Mot de passe (facultatif)'}<input type="password" minlength="12" maxlength="1024" autocomplete="new-password" bind:value={password}/></label><small>{selected.id?'Laissez vide pour conserver le mot de passe actuel. Un nouveau mot de passe déconnecte toutes les sessions de ce compte.':'Si vous laissez ce champ vide, l’utilisateur choisira son propre mot de passe à la première connexion, grâce au lien d’invitation.'}</small>
<label class="account-check"><input type="checkbox" bind:checked={selected.admin} disabled={selected.id===user.id}/>Administrateur — accès à tous les réglages et bibliothèques</label>
{#if selected.id}<label class="account-check"><input type="checkbox" bind:checked={selected.disabled} disabled={selected.id===user.id}/>Désactiver ce compte (ses données restent conservées)</label>{/if}
{#if !selected.admin}<fieldset><legend>Types de médias autorisés</legend>{#each Object.keys(names) as value}{@const k=value as Kind}<label class="account-check"><input type="checkbox" checked={selected.kinds.includes(k)} onchange={e=>kind(k,e.currentTarget.checked)}/>{names[k]}</label>{/each}</fieldset>
<fieldset><legend>Accès aux bibliothèques</legend><p>Une nouvelle bibliothèque reste privée tant que vous ne l’autorisez pas ici.</p>{#each libraries as l}<div class="library-grants"><strong>{l.name}</strong>{#each actions as action}<label class="account-check"><input type="checkbox" checked={!!selected.libraries[l.id]?.[action.id]} disabled={!selected.kinds.includes(l.kind as Kind)} onchange={e=>grant(l.id,action.id,e.currentTarget.checked)}/>{action.label}</label>{/each}</div>{/each}{#if !libraries.length}<p>Ajoutez d’abord un dossier dans Bibliothèques.</p>{/if}</fieldset>{/if}
<div class="account-buttons"><button class="primary" disabled={busy}>{busy?'Enregistrement…':'Enregistrer le compte'}</button>{#if selected.id&&selected.pending&&!selected.disabled}<button type="button" class="secondary" disabled={busy} onclick={renew}>Renouveler l’invitation</button>{/if}<button type="button" class="text-action" onclick={()=>selected=null}>Fermer</button></div></form>{/if}
{#if invitation}<div class="invitation-box"><h3>Lien d’invitation</h3><p>Valable sept jours et utilisable une seule fois. Il donne accès au compte : transmettez-le uniquement à son destinataire.</p><label>Lien à transmettre<input readonly value={invitation} onclick={e=>e.currentTarget.select()}/></label><button class="secondary" onclick={copy}>Copier le lien</button><p>Pour cet essai local, ouvrez le lien sur cet ordinateur dans un autre navigateur ou une fenêtre privée.</p></div>{/if}
{:else}<span class="eyebrow">VOTRE ESPACE PERSONNEL</span><h2>{user.name}</h2><p>{user.admin?'Administrateur':'Utilisateur'} · Votre progression, vos favoris et vos playlists vous appartiennent.</p>
<label>Apparence<select bind:value={theme} onchange={saveTheme}><option value="light">Clair</option><option value="dark">Sombre</option><option value="system">Suivre l’appareil</option></select></label>
<p class="folder-help">Langue : français. D’autres langues arriveront avec les extensions de traduction.</p>
<form class="account-editor" onsubmit={changePassword}><h3>Changer mon mot de passe</h3><label>Mot de passe actuel<input type="password" required autocomplete="current-password" bind:value={current}/></label><label>Nouveau mot de passe<input type="password" required minlength="12" maxlength="1024" autocomplete="new-password" bind:value={password}/></label><label>Confirmer le nouveau mot de passe<input type="password" required autocomplete="new-password" bind:value={repeat}/></label><p>Cette opération vous déconnectera sur tous vos appareils.</p><button class="secondary" disabled={busy}>Modifier le mot de passe</button></form>
<button class="text-action" onclick={logout}>Me déconnecter</button>{/if}
{#if error}<p class="form-error" role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
</section>
